	} else {
		uint64_t offset = 0;
		if (!_pool_allocate(pool_index, sa.size, sa.align, result.allocation, heap, offset)) {
			return result;
		}
		result.buffer = NS::TransferPtr(heap->newBuffer(p_length, heap_options, offset));
